StructuredTextModel.Text:
(*
================================================================================
 SDO_WriteReadBack  -  Generic EtherCAT CoE SDO write + read-back function block
                        for Omron Sysmac Studio (NJ/NX-series), Structured Text.
================================================================================
 
WHAT IT DOES
  - Execute (rising edge): writes WriteData to the given slave/Index/SubIndex
    via SDO, then automatically reads the same object back for verification.
  - ReadOnly (rising edge): reads the given slave/Index/SubIndex back without
    writing anything first.
  - NodeAdr, Index, SubIndex, and DataSize are all runtime inputs, so ONE
    instance of this FB can be reused for any slave, any object, any size
    just by changing the inputs before pulsing Execute or ReadOnly.
  - Message always contains a human-readable explanation of the current
    result: success text on Done, or a decoded description of ErrorID (and,
    for SDO aborts, the decoded AbortCode too) on Error. All of the error
    decoding is inlined directly in this FB - no separate Function POUs
    required.
 
WHY Message IS A VAR_IN_OUT, NOT A VAR_OUTPUT
  Sysmac Studio does not allow STRING as a function block VAR_OUTPUT. The
  standard workaround is to declare it as VAR_IN_OUT instead: the calling
  program declares an ordinary STRING variable and passes it in, and this FB
  writes the result directly into it (by reference). Practically, this just
  means Message is wired at the call site the same way any other parameter
  is, except the variable you connect to it must be a real STRING variable
  you've declared - not a literal.
 
HOW TO USE IN SYSMAC STUDIO
  1. Create one Function Block POU: "SDO_WriteReadBack" (ST). Paste the code
     below into it - everything needed is self-contained in this one FB.
  2. In the calling program, declare a STRING variable for the message and
     call one FB instance per SDO object you want to manage, e.g.:
 
        VAR
            fbSdo1    : SDO_WriteReadBack;
            sSdo1Msg  : STRING[256];   // owned by the caller, passed by reference
        END_VAR
 
        fbSdo1(
            Execute    := bWriteAndVerify,
            ReadOnly   := bReadOnly,
            NodeAdr    := 3,              // slave node address
            Index      := 16#2101,        // example manufacturer-specific object
            SubIndex   := 1,
            DataSize   := 2,               // 2 bytes = UINT/INT sized parameter
            WriteData  := aWriteBuf,       // ARRAY[0..7] OF BYTE, low DataSize bytes used
            SDOTimeout := T#2S,
            Message    := sSdo1Msg );
 
     Display sSdo1Msg on your HMI screen / log it whenever fbSdo1.Done or
     fbSdo1.Error pulses TRUE.
  3. The FB instance must be called EVERY SCAN (put it in a cyclic task, not
     an event task) while a transfer is in progress - this is standard for
     all of Omron's asynchronous "Execute/Busy/Done" instructions.
 
IMPORTANT - VERIFY BEFORE USE
  The EC_CoESDOWrite / EC_CoESDORead pin names (SdoObj, WriteDat, WriteSize,
  ReadDat, ReadSize, AbortCode) are per the NJ/NX-series Instructions
  Reference Manual (W502). Before deploying, drop EC_CoESDOWrite and
  EC_CoESDORead onto an ST line in your actual project and press F1 to
  confirm exact pin names for your installed Sysmac Studio version.
 
  ErrorID decoding covers the documented error set for EtherCAT CoE SDO
  communications instructions (16#0000-16#1808: input range, EtherCAT
  network/slave/timeout/buffer/resource errors, and the 16#1804 "SDO Abort"
  code that hands off to AbortCode). Any ErrorID outside that set still
  produces a message (shown as a decimal value) rather than nothing, but it
  falls outside this FB's lookup table - cross-check it against Appendix A-1
  of the W502 manual.
 
  AbortCode decoding covers the full standard CANopen/CoE SDO abort code set
  defined by CiA DS301 (used identically by Omron and every other CoE
  master/slave vendor) - this list does not vary by PLC brand.
 
SIZE LIMIT
  WriteData/ReadData are ARRAY[0..7] OF BYTE (8 bytes), covering all common
  scalar CoE types (BOOL/USINT=1, UINT/INT=2, UDINT/DINT/REAL=4,
  ULINT/LINT/LREAL=8). If you need to read/write a longer object (e.g. a
  VISIBLE_STRING / manufacturer name field), enlarge both arrays and the
  DataSize bounds check in Step 0 accordingly.
================================================================================
*)
//---------------------------------------------------------------------------
trigWrite(CLK := Execute);
trigRead(CLK := ReadOnly);
 
CASE Step_No OF
 
0: // IDLE - wait for a trigger
    Done  := FALSE;
    Error := FALSE;
 
    IF trigWrite.Q AND DataSize >= 1 AND DataSize <= 8 THEN
        NodeAdrL        := NodeAdr;
        SdoObj.Index    := Index;
        SdoObj.SubIndex := SubIndex;
        DataSizeL       := DataSize;
        WriteDataL      := WriteData;
        ErrorID         := 16#0000;
        AbortCode       := 16#00000000;
        Message         := '';
        Step_No := 10;
 
    ELSIF trigRead.Q AND DataSize >= 1 AND DataSize <= 8 THEN
        NodeAdrL        := NodeAdr;
        SdoObj.Index    := Index;
        SdoObj.SubIndex := SubIndex;
        ErrorID         := 16#0000;
        AbortCode       := 16#00000000;
        Message         := '';
        Step_No := 30;
 
    ELSIF (trigWrite.Q OR trigRead.Q) THEN
        // Triggered with DataSize out of the supported 1-8 byte range.
        // This is a local input-validation failure - no SDO transfer was
        // attempted, so ErrorID 16#FFFF is used as a local-only marker
        // (it is never returned by the actual instructions).
        Error   := TRUE;
        ErrorID := 16#FFFF;
        Message := 'DataSize out of range (must be 1-8 bytes) - request rejected before any SDO transfer was attempted.';
    END_IF;
 
10: // WRITE - call every scan until Done or Error
    Busy := TRUE;
    fbWrite(
        Execute   := TRUE,
        NodeAdr   := NodeAdrL,
        SdoObj    := SdoObj,
        TimeOut   := SDOTimeout,
        WriteDat  := WriteDataL,
        WriteSize := DataSizeL );
 
    IF fbWrite.Done THEN
        fbWrite(Execute := FALSE, NodeAdr := NodeAdrL, SdoObj := SdoObj,
                TimeOut := SDOTimeout, WriteDat := WriteDataL, WriteSize := DataSizeL);
        Step_No := 30;                      // proceed straight to read-back
    ELSIF fbWrite.Error THEN
        ErrorID   := fbWrite.ErrorID;
        AbortCode := fbWrite.AbortCode;
        fbWrite(Execute := FALSE, NodeAdr := NodeAdrL, SdoObj := SdoObj,
                TimeOut := SDOTimeout, WriteDat := WriteDataL, WriteSize := DataSizeL);
        Step_No := 99;
    END_IF;
 
30: // READ-BACK - call every scan until Done or Error
    Busy := TRUE;
    fbRead(
        Execute := TRUE,
        NodeAdr := NodeAdrL,
        SdoObj  := SdoObj,
        TimeOut := SDOTimeout,
        ReadDat := ReadData );
 
    IF fbRead.Done THEN
        ReadSize := fbRead.ReadSize;
        fbRead(Execute := FALSE, NodeAdr := NodeAdrL, SdoObj := SdoObj,
               TimeOut := SDOTimeout, ReadDat := ReadData);
        Step_No := 90;
    ELSIF fbRead.Error THEN
        ErrorID   := fbRead.ErrorID;
        AbortCode := fbRead.AbortCode;
        fbRead(Execute := FALSE, NodeAdr := NodeAdrL, SdoObj := SdoObj,
               TimeOut := SDOTimeout, ReadDat := ReadData);
        Step_No := 99;
    END_IF;
 
90: // COMPLETE
    Busy    := FALSE;
    Done    := TRUE;
    Message := 'OK - SDO transfer completed successfully.';
    Step_No    := 0;
 
99: // FAULT - decode ErrorID (and AbortCode, if applicable) directly, in place
    Busy  := FALSE;
    Error := TRUE;
 
IF ErrorID <> 16#FFFF THEN   // 16#FFFF already got its message in Step 0
        IF ErrorID = 16#0000 THEN
            Message := 'Normal end - no error.';
        ELSIF ErrorID = 16#0400 THEN
            Message := 'Input value out of range - check NodeAdr.';
        ELSIF ErrorID = 16#1800 THEN
            Message := 'EtherCAT communications error - network is not in a usable state; check the EtherCAT master status.';
        ELSIF ErrorID = 16#1801 THEN
            Message := 'EtherCAT slave does not respond - the node does not exist or is not in an operating state.';
        ELSIF ErrorID = 16#1802 THEN
            Message := 'EtherCAT SDO communications timeout - check the target slave and increase SDOTimeout if needed.';
        ELSIF ErrorID = 16#1803 THEN
            Message := 'Reception buffer overflow - the slave returned more data than the receive buffer can hold.';
        ELSIF ErrorID = 16#1804 THEN
            // SDO abort - decode AbortCode inline (standard CANopen/CoE CiA DS301 codes)
            IF AbortCode = 16#00000000 THEN
                Message := 'SDO abort received from the slave, but AbortCode = 0 (no further detail supplied).';
            ELSIF AbortCode = 16#05030000 THEN
                Message := 'SDO Abort: Toggle bit not changed.';
            ELSIF AbortCode = 16#05040000 THEN
                Message := 'SDO Abort: SDO protocol timed out.';
            ELSIF AbortCode = 16#05040001 THEN
                Message := 'SDO Abort: Client/server command specifier not valid or unknown.';
            ELSIF AbortCode = 16#05040002 THEN
                Message := 'SDO Abort: Invalid block size (block transfer mode).';
            ELSIF AbortCode = 16#05040003 THEN
                Message := 'SDO Abort: Invalid sequence number (block transfer mode).';
            ELSIF AbortCode = 16#05040004 THEN
                Message := 'SDO Abort: CRC error (block transfer mode).';
            ELSIF AbortCode = 16#05040005 THEN
                Message := 'SDO Abort: Out of memory.';
            ELSIF AbortCode = 16#06010000 THEN
                Message := 'SDO Abort: Unsupported access to an object.';
            ELSIF AbortCode = 16#06010001 THEN
                Message := 'SDO Abort: Attempt to read a write-only object.';
            ELSIF AbortCode = 16#06010002 THEN
                Message := 'SDO Abort: Attempt to write a read-only object.';
            ELSIF AbortCode = 16#06020000 THEN
                Message := 'SDO Abort: Object does not exist in the object dictionary.';
            ELSIF AbortCode = 16#06040041 THEN
                Message := 'SDO Abort: Object cannot be mapped to the PDO.';
            ELSIF AbortCode = 16#06040042 THEN
                Message := 'SDO Abort: Number and/or length of mapped objects would exceed PDO length.';
            ELSIF AbortCode = 16#06040043 THEN
                Message := 'SDO Abort: General parameter incompatibility reason.';
            ELSIF AbortCode = 16#06040047 THEN
                Message := 'SDO Abort: General internal incompatibility in the device.';
            ELSIF AbortCode = 16#06060000 THEN
                Message := 'SDO Abort: Access failed due to a hardware error.';
            ELSIF AbortCode = 16#06070010 THEN
                Message := 'SDO Abort: Data type / length of service parameter does not match.';
            ELSIF AbortCode = 16#06070012 THEN
                Message := 'SDO Abort: Data type does not match - parameter length too high.';
            ELSIF AbortCode = 16#06070013 THEN
                Message := 'SDO Abort: Data type does not match - parameter length too low.';
            ELSIF AbortCode = 16#06090011 THEN
                Message := 'SDO Abort: Sub-index does not exist.';
            ELSIF AbortCode = 16#06090030 THEN
                Message := 'SDO Abort: Value range of parameter exceeded (write access).';
            ELSIF AbortCode = 16#06090031 THEN
                Message := 'SDO Abort: Value of parameter written is too high.';
            ELSIF AbortCode = 16#06090032 THEN
                Message := 'SDO Abort: Value of parameter written is too low.';
            ELSIF AbortCode = 16#06090036 THEN
                Message := 'SDO Abort: Maximum value is less than minimum value.';
            ELSIF AbortCode = 16#060A0023 THEN
                Message := 'SDO Abort: Resource not available - SDO connection.';
            ELSIF AbortCode = 16#08000000 THEN
                Message := 'SDO Abort: General error.';
            ELSIF AbortCode = 16#08000020 THEN
                Message := 'SDO Abort: Data cannot be transferred or stored to the application.';
            ELSIF AbortCode = 16#08000021 THEN
                Message := 'SDO Abort: Data cannot be transferred/stored - local control.';
            ELSIF AbortCode = 16#08000022 THEN
                Message := 'SDO Abort: Data cannot be transferred/stored - present device state.';
            ELSIF AbortCode = 16#08000023 THEN
                Message := 'SDO Abort: Object dictionary dynamic generation failed, or no object dictionary is present.';
            ELSIF AbortCode = 16#08000024 THEN
                Message := 'SDO Abort: No data available.';
            ELSE
                AbortCodeStr := DWORD_TO_STRING(AbortCode);
                Message := CONCAT('SDO Abort: unlisted AbortCode (decimal = ', AbortCodeStr, ') - check the target slaves own manual for a manufacturer-specific code.');
            END_IF;
        ELSIF ErrorID = 16#1808 THEN
            Message := 'Communications resource overflow - more than 32 EtherCAT communications instructions executing at the same time.';
        ELSE
            ErrorIDStr := WORD_TO_STRING(ErrorID);
            Message := CONCAT('Unlisted ErrorID (decimal = ', CONCAT(ErrorIDStr, ') - refer to NJ/NX Instructions Reference Manual (W502) Appendix A-1.'));
        END_IF;
    END_IF;
    Step_No := 0;
 
END_CASE;
